  async function sendVoiceMailToMailbox(){if(!memoBlob)return toast('Record a voice mail first.');if(memoBlob.size>MAX_VOICE_BYTES)return status('scrVmMailboxState','Voice mail is larger than 8 MiB. Record a shorter message or download it for another authorised transfer method.','warn');try{const parsed=parseMailboxKey($('scrVmRecipientInboxKey')?.value);const meta=voiceMailMeta();status('scrVmMailboxState','Encrypting voice and details in this browser before upload…','warn');const encrypted=await encryptMailboxVoice(parsed,memoBlob,meta);const result=await postMailApi('send',encrypted);status('scrVmMailboxState','Encrypted voice mail delivered to temporary internet mailbox. Receipt ID: '+result.message.id+'. It expires within 24 hours and may be lost if the relay restarts. This is not a satellite transmission.','live');if($('scrVmDelivery'))$('scrVmDelivery').textContent='ENCRYPTED INTERNET MAIL SENT';}catch(e){status('scrVmMailboxState',e.message||String(e),'bad');}}
