  function configureIce(){const servers=[{urls:'stun:stun.l.google.com:19302'}],raw=String($('scrTurnServers')?.value||'').trim();if(raw){let extra;try{extra=JSON.parse(raw);}catch{throw new Error('Optional TURN/ICE configuration is not valid JSON.');}if(!Array.isArray(extra)||extra.length>4||extra.some(x=>!x||!(typeof x.urls==='string'||Array.isArray(x.urls))))throw new Error('ICE config must be an array of up to four server objects.');for(const x of extra){const urls=Array.isArray(x.urls)?x.urls:[x.urls];if(urls.some(u=>typeof u!=='string'||! /^(stun|stuns|turn|turns):/i.test(u)))throw new Error('ICE URLs must start with stun:, stuns:, turn: or turns:.');servers.push({urls:x.urls,...(x.username?{username:String(x.username)}:{}),...(x.credential?{credential:String(x.credential)}:{})});}}RTC_CONFIG={iceServers:servers};}
