  function receiveVoiceMeta(p){if(!MathAPI.validateVoiceMeta(p)){status('scrVmState','Rejected invalid or oversized voice-mail transfer.','warn');return;}if(incomingVoiceTransfers.has(p.transferId))return;if(incomingVoiceTransfers.size>=4){status('scrVmState','Too many incomplete voice-mail transfers; finish or reset the current session first.','warn');return;}incomingVoiceTransfers.set(p.transferId,{meta:p,chunks:new Array(p.totalChunks),received:0,bytes:0});status('scrVmState','Receiving voice mail: '+String(p.metadata?.subject||'message').slice(0,120),'warn');}
  function receiveVoiceChunk(buffer){if(!(buffer instanceof ArrayBuffer)||buffer.byteLength<41||buffer.byteLength>VOICE_CHUNK_BYTES+40)return;const view=new Uint8Array(buffer),id=new TextDecoder().decode(view.slice(0,36)),t=incomingVoiceTransfers.get(id);if(!t)return;const seq=new DataView(buffer).getUint32(36,false);if(seq>=t.meta.totalChunks||t.chunks[seq])return;const payload=buffer.slice(40);t.chunks[seq]=payload;t.received++;t.bytes+=payload.byteLength;if(t.bytes>MAX_VOICE_BYTES){incomingVoiceTransfers.delete(id);status('scrVmState','Incoming voice mail exceeded size limit and was discarded.','warn');return;}if(t.received===t.meta.totalChunks){incomingVoiceTransfers.delete(id);const blob=new Blob(t.chunks,{type:t.meta.mimeType});if(blob.size!==t.meta.sizeBytes){status('scrVmState','Voice mail failed its integrity-size check.','bad');return;}showReceivedVoiceMail(t.meta,blob);try{dataChannel?.send(JSON.stringify({type:'voice-mail-received',transferId:id}));}catch{}}}
